#!/bin/bash
# Generates the Magnolia property overlay from env vars, then starts Tomcat.
# Overlay file: WEB-INF/config/magnoliaAuthor/magnolia.properties (loaded before WEB-INF/config/default/magnolia.properties,
# first definition wins), so everything persistent lives under /data (bind-mounted env/<ver>/data).
set -euo pipefail

W="${MGNL_WEBAPP_DIR:-/usr/local/tomcat/webapps/magnoliaAuthor}"
: "${MGNL_UPDATE_AUTO:=true}"      # true = run install/update tasks at startup without the web installer
: "${MGNL_JCR:=h2}"                # h2 | derby (Jackrabbit bundle persistence manager, embedded)
: "${MGNL_DEVELOP:=false}"
: "${MGNL_LOG_UPDATES:=true}"      # true = log4j2-sandbox.xml with DEBUG update/task logging + magnolia-update.log
: "${MGNL_BOOTSTRAP_SAMPLES:=true}"
: "${MGNL_SUPERUSER_PASSWORD:=superuser}"  # 6.4+: magnolia.superuser.bootstrap.password (skips /.magnolia/adminsetup form); ignored by 6.3
: "${JAVA_XMS:=512m}"
: "${JAVA_XMX:=2g}"

mkdir -p /data/repositories /data/logs /data/keys /data/cache /data/tmp /data/history /data/light-modules

# A repository created with one persistence manager must keep using it.
if [ -f /data/.mgnl-jcr ] && [ "$(cat /data/.mgnl-jcr)" != "$MGNL_JCR" ]; then
  echo "[mgnl-entrypoint] WARNING: /data was created with MGNL_JCR=$(cat /data/.mgnl-jcr), forcing it" >&2
  MGNL_JCR="$(cat /data/.mgnl-jcr)"
fi
echo "$MGNL_JCR" > /data/.mgnl-jcr

LOGCFG=WEB-INF/config/default/log4j2.xml
[ "$MGNL_LOG_UPDATES" = "true" ] && LOGCFG=WEB-INF/config/default/log4j2-sandbox.xml

cat > "$W/WEB-INF/config/magnoliaAuthor/magnolia.properties" <<EOF
# generated by mgnl-entrypoint.sh at $(date -Iseconds)
magnolia.bootstrap.dir=WEB-INF/bootstrap/author WEB-INF/bootstrap/common
magnolia.personalization.rest.allowVariants=true
magnolia.repositories.home=/data/repositories
magnolia.repositories.jackrabbit.config=WEB-INF/config/repo-conf/jackrabbit-bundle-${MGNL_JCR}-search.xml
magnolia.logs.dir=/data/logs
magnolia.cache.startdir=/data/cache
magnolia.upload.tmpdir=/data/tmp
magnolia.exchange.history=/data/history
magnolia.resources.dir=/data/light-modules
magnolia.author.key.location=/data/keys/magnolia-activation-keypair.properties
magnolia.password.manager.key.location=/data/keys/magnolia-password-manager-keypair.properties
magnolia.update.auto=${MGNL_UPDATE_AUTO}
magnolia.develop=${MGNL_DEVELOP}
magnolia.bootstrap.samples=${MGNL_BOOTSTRAP_SAMPLES}
log4j.config=${LOGCFG}
# 6.4+ (AdminSetupConfig): superuser is disabled on fresh install until a password is set; set it non-interactively
magnolia.superuser.bootstrap.password=${MGNL_SUPERUSER_PASSWORD}
EOF
if [ -n "${MGNL_EXTRA_PROPERTIES:-}" ]; then   # newline- or ';'-separated key=value pairs
  echo "$MGNL_EXTRA_PROPERTIES" | tr ';' '\n' >> "$W/WEB-INF/config/magnoliaAuthor/magnolia.properties"
fi

# Keep a record of which Magnolia version touched this repository (useful for upgrade tests)
echo "$(date -Iseconds) start $(cat /usr/local/tomcat/MAGNOLIA_ARTIFACT) jcr=$MGNL_JCR auto=$MGNL_UPDATE_AUTO" >> /data/versions.log

export CATALINA_OPTS="-Xms${JAVA_XMS} -Xmx${JAVA_XMX} -Djava.awt.headless=true -Dfile.encoding=UTF-8 ${CATALINA_OPTS:-}"
echo "[mgnl-entrypoint] $(cat /usr/local/tomcat/MAGNOLIA_ARTIFACT) jcr=$MGNL_JCR update.auto=$MGNL_UPDATE_AUTO log=$LOGCFG CATALINA_OPTS=$CATALINA_OPTS"
exec "$@"
